create table public.trips(id uuid primary key default gen_random_uuid(), name text not null, invite_code text unique not null default replace(gen_random_uuid()::text,'-',''));
create table public.members(trip_id uuid references trips not null,user_id uuid references auth.users not null,name text not null,primary key(trip_id,user_id));
create table public.expenses(id uuid primary key default gen_random_uuid(),trip_id uuid references trips not null,buyer uuid not null,item text not null,qty text,amount integer not null check(amount>0),category text not null,people uuid[] not null check(cardinality(people)>0),receipt text not null,created_at timestamptz default now(),foreign key(trip_id,buyer) references members);
create table public.payments(id uuid primary key default gen_random_uuid(),trip_id uuid references trips not null,sender uuid not null,receiver uuid not null,amount integer not null check(amount>0),method text not null,created_at timestamptz default now(),check(sender<>receiver),foreign key(trip_id,sender) references members,foreign key(trip_id,receiver) references members);
create table public.items(id uuid primary key default gen_random_uuid(),trip_id uuid references trips not null,title text not null,owner uuid,done boolean not null default false,foreign key(trip_id,owner) references members);
create function public.is_member(t uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from members where trip_id=t and user_id=auth.uid())$$;
create function public.valid_people(t uuid,p uuid[]) returns boolean language sql stable security definer set search_path=public as $$select cardinality(p)>0 and cardinality(p)=(select count(distinct m.user_id) from members m where m.trip_id=t and m.user_id=any(p))$$;
create function public.create_trip(title text,display_name text) returns uuid language plpgsql security definer set search_path=public as $$declare t uuid; begin if auth.uid() is null or trim(title)='' or trim(display_name)='' then raise exception 'Datos inválidos'; end if; insert into trips(name) values(title) returning id into t; insert into members values(t,auth.uid(),display_name); return t; end$$;
create function public.join_trip(invite text,display_name text) returns uuid language plpgsql security definer set search_path=public as $$declare t uuid; begin if auth.uid() is null or trim(display_name)='' then raise exception 'Datos inválidos'; end if; select id into t from trips where invite_code=invite; if t is null then raise exception 'Código inválido'; end if; insert into members values(t,auth.uid(),display_name) on conflict do nothing; return t; end$$;
revoke execute on function public.create_trip(text,text),public.join_trip(text,text),public.is_member(uuid),public.valid_people(uuid,uuid[]) from public,anon;
grant execute on function public.create_trip(text,text),public.join_trip(text,text),public.is_member(uuid),public.valid_people(uuid,uuid[]) to authenticated;
alter table trips enable row level security; alter table members enable row level security; alter table expenses enable row level security; alter table payments enable row level security; alter table items enable row level security;
create policy trip_read on trips for select to authenticated using(is_member(id));
create policy member_read on members for select to authenticated using(is_member(trip_id));
create policy expense_read on expenses for select to authenticated using(is_member(trip_id));
create policy expense_add on expenses for insert to authenticated with check(is_member(trip_id) and buyer=auth.uid() and valid_people(trip_id,people) and split_part(receipt,'/',1)=trip_id::text and split_part(receipt,'/',2)=auth.uid()::text and exists(select 1 from storage.objects where bucket_id='receipts' and name=receipt));
create policy payment_read on payments for select to authenticated using(is_member(trip_id));
create policy payment_add on payments for insert to authenticated with check(is_member(trip_id) and sender=auth.uid());
create policy item_read on items for select to authenticated using(is_member(trip_id));
create policy item_add on items for insert to authenticated with check(is_member(trip_id));
create policy item_update on items for update to authenticated using(is_member(trip_id)) with check(is_member(trip_id));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('receipts','receipts',false,8388608,array['image/jpeg','image/png','image/webp']);
create policy receipt_read on storage.objects for select to authenticated using(bucket_id='receipts' and is_member((storage.foldername(name))[1]::uuid));
create policy receipt_add on storage.objects for insert to authenticated with check(bucket_id='receipts' and is_member((storage.foldername(name))[1]::uuid) and (storage.foldername(name))[2]=auth.uid()::text);
create policy receipt_cleanup on storage.objects for delete to authenticated using(bucket_id='receipts' and (storage.foldername(name))[2]=auth.uid()::text and not exists(select 1 from public.expenses e where e.receipt=storage.objects.name));
alter publication supabase_realtime add table public.members,public.expenses,public.payments,public.items;
